import re

SHOW = re.compile(r"^SQL> SHOW TABLE (?P<table>\S+?);?\s*$")
PROMPT = re.compile(r"^SQL> ")
CONSTRAINT = re.compile(r"^CONSTRAINT (?P<name>\S+):\s*$")
TRIGGERS = re.compile(r"^Triggers on Table (?P<table>\S+):\s*$")
TRIGGER = re.compile(r"^(?P<trigger>\S+), Sequence: (?P<sequence>\d+), Type: (?P<type>[A-Z ]+?), (?P<status>\S+)\s*$")
COLUMN = re.compile(r"^(?P<column>\S+)\s{2,}(?P<rest>\S.*)$")
NULL = re.compile(r"\s+(?P<null>Not Null|Nullable)(?=\s|$)")
TAIL = re.compile(r"^(?:\s*DEFAULT\s+(?P<default>.*?))?(?:\s*COLLATE\s+(?P<collate>\S+))?(?:\s*(?P<check>CHECK\s*\(.*\)))?\s*$")
DEFN = re.compile(r"^(?P<kind>Foreign key|Primary key|Unique key|CHECK)\s*(?P<cols>\([^)]*\))?(?:\s+(?P<clause>\S.*?))?\s*$")


def _column(text, table):
    m = COLUMN.match(text)
    if not m:
        return None
    rest, rec = m.group("rest").strip(), {"Table": table, "Column": m.group("column"),
                                          "Type": "", "Nullability": "", "Default": "", "Check": ""}
    n = NULL.search(rest)
    if not n:
        rec["Type"] = rest
        return rec
    rec["Type"], rec["Nullability"] = rest[:n.start()].strip(), n.group("null")
    t = TAIL.match(rest[n.end():])
    if t:
        rec["Default"] = (t.group("default") or "").strip()
        rec["Check"] = t.group("check") or ""
        if t.group("collate"):
            rec["Type"] += " COLLATE " + t.group("collate")
    else:
        rec["Type"] += " " + rest[n.end():].strip()
    return rec


def _constraint(name, text, table):
    m = DEFN.match(text.strip())
    if not m:
        return {"Table": table, "Constraint": name, "Kind": "", "Columns": "", "Clause": text.strip()}
    cols, clause = m.group("cols") or "", m.group("clause") or ""
    if m.group("kind") == "CHECK":
        cols, clause = "", (cols + " " + clause).strip()
    return {"Table": table, "Constraint": name, "Kind": m.group("kind"), "Columns": cols, "Clause": clause}


def parse(lines):
    columns = {"name": "columns", "kind": "table", "lines": [], "records": []}
    constraints = {"name": "constraints", "kind": "table", "lines": [], "records": []}
    triggers = {"name": "triggers", "kind": "table", "lines": [], "records": []}
    skip, table, mode = [], "", "columns"
    items = []  # (block, name, text, line indexes) built up, then flushed
    for i, ln in enumerate(lines):
        if not ln.strip():
            continue
        m = SHOW.match(ln)
        if m:
            table = m.group("table")
        if PROMPT.match(ln):
            skip.append(i)
            continue
        m = CONSTRAINT.match(ln)
        if m:
            items.append(["constraint", m.group("name"), "", [i]])
            mode = "constraints"
            continue
        m = TRIGGERS.match(ln)
        if m:
            table, mode = m.group("table"), "triggers"
            triggers["lines"].append(i)
            continue
        if mode == "triggers":
            m = TRIGGER.match(ln)
            if m:
                triggers["lines"].append(i)
                triggers["records"].append({"Table": table, "Trigger": m.group("trigger"),
                                            "Sequence": m.group("sequence"), "Type": m.group("type"),
                                            "Status": m.group("status")})
            continue
        if ln[0].isspace() and items:
            items[-1][2] = (items[-1][2] + " " + ln.strip()).strip()
            items[-1][3].append(i)
        elif mode == "columns":
            items.append(["column", "", ln.rstrip(), [i]])
    for kind, name, text, idx in items:
        if kind == "column":
            rec = _column(text, table)
            if rec:
                columns["records"].append(rec)
                columns["lines"] += idx
        else:
            constraints["records"].append(_constraint(name, text, table))
            constraints["lines"] += idx
    return {"blocks": [columns, constraints, triggers], "skip": skip}
